list_tax_country_taxes.code:
import {taxCountryTaxes} from 'webcommander-sdk';

const response = await taxCountryTaxes.listTaxCountryTaxes(client, {limit: 20});
for (const countryTax of response.map.country_taxes) {
    console.log(countryTax.id, countryTax.name, countryTax.rate_display);
}
console.log(response.map.pagination.total);

create_tax_country_tax.code:
import {taxCountryTaxes} from 'webcommander-sdk';

const countryTax = {
    country_code: 'NZ',
    name: 'New Zealand',
    tax_rate: 4.5,
    tax_method: 'FIXED_RATE',
    is_default: false,
};
const response = await taxCountryTaxes.createTaxCountryTax(client, {country_tax: countryTax});
console.log(response.map.country_tax.id, response.map.country_tax.rate_display);

get_tax_country_tax.code:
import {taxCountryTaxes} from 'webcommander-sdk';

const response = await taxCountryTaxes.getTaxCountryTax(client, 4);
const countryTax = response.map.country_tax;
console.log(countryTax.name, countryTax.tax_rate, countryTax.rate_display);
for (const stateRule of countryTax.state_rules) {
    console.log(stateRule.id, stateRule.tax_rule, stateRule.effective_tax_rate);
}

update_tax_country_tax.code:
import {taxCountryTaxes} from 'webcommander-sdk';

const response = await taxCountryTaxes.updateTaxCountryTax(client, 42, {country_tax: {tax_rate: 6.25}});
console.log(response.map.country_tax.tax_rate, response.map.country_tax.rate_display);

